class GetLayerInpOut:
    def __init__(
        self,
        model: QuantModel,
        layer: nn.Module, # Can be QuantModule or BaseQuantBlock
        device: torch.device,
        wq: bool = False,
        aq: bool = False,
        input_prob: bool = False,
    ):
        self.model = model
        self.layer = layer
        self.device = device
        self.wq = wq
        self.aq = aq
        self.data_saver = DataSaverHook(
            store_input=True, store_output=True, stop_forward=True
        )
        self.input_prob = input_prob

    def __call__(self, model_input):
        self.model.set_quant_state(False, False)

        handle = self.layer.register_forward_hook(self.data_saver)
        with torch.no_grad():
            try:
                _ = self.model(*[_.to(self.device) for _ in model_input])
            except StopForwardException:
                pass
            input_sym = self.data_saver.input_store[0].detach() if self.input_prob else None
            if self.wq or self.aq:
                self.data_saver.store_output = False
                self.model.set_quant_state(weight_quant=self.wq, act_quant=self.aq)
                try:
                    _ = self.model(*[_.to(self.device) for _ in model_input])
                except StopForwardException:
                    pass

            self.data_saver.store_output = True
        handle.remove()

        if self.input_prob:
            return (
                self.data_saver.input_store[0].detach(),
                self.data_saver.output_store.detach(),
                input_sym,
            )
        return (
            self.data_saver.input_store[0].detach(),
            self.data_saver.output_store.detach(),
        )

def save_inp_oup_data(
    model: QuantModel,
    layer: nn.Module, # Can be QuantModule or BaseQuantBlock
    cali_data: torch.Tensor,
    wq: bool = False,
    aq: bool = False,
    batch_size: int = 32,
    keep_gpu: bool = True,
    input_prob: bool = False,
):
    device = next(model.parameters()).device
    get_inp_out = GetLayerInpOut(
        model, layer, device=device, wq=wq, aq=aq, input_prob=input_prob
    )
    cached_batches = []

    # Handle cali_data potentially being a tuple (data, t, class_labels)
    data_only = cali_data[0] if isinstance(cali_data, tuple) else cali_data
    batch_len = data_only.size(0)

    for i in range(int(batch_len / batch_size)):
        current_batch = []
        if isinstance(cali_data, tuple): # If calibration data includes t and/or labels
            for item in cali_data:
                current_batch.append(item[i * batch_size : (i + 1) * batch_size])
        else: # Standard calibration data
            current_batch.append(cali_data[i * batch_size : (i + 1) * batch_size])

        if input_prob:
            cur_inp, cur_out, cur_sym = get_inp_out(current_batch)
            cached_batches.append((cur_inp.cpu(), cur_out.cpu(), cur_sym.cpu()))
        else:
            cur_inp, cur_out = get_inp_out(current_batch)
            cached_batches.append((cur_inp.cpu(), cur_out.cpu()))
    cached_inps = torch.cat([x[0] for x in cached_batches])
    cached_outs = torch.cat([x[1] for x in cached_batches])
    if input_prob:
        cached_sym = torch.cat([x[2] for x in cached_batches])
    torch.cuda.empty_cache()
    if keep_gpu:
        cached_inps = cached_inps.to(device)
        cached_outs = cached_outs.to(device)
        if input_prob:
            cached_sym = cached_sym.to(device)
    if input_prob:
        return (cached_inps, cached_sym), cached_outs
    return (cached_inps,), cached_outs

