def set_act_quantize_params(
    module: nn.Module, # Can be QuantModel, QuantModule, BaseQuantBlock
    cali_data,
    awq: bool = False,
    order: str = "before",
    batch_size: int = 256,
):
    weight_quant, act_quant = act_get_quant_state(order, awq)
    module.set_quant_state(weight_quant, act_quant)

    for t in module.modules():
        if isinstance(t, (QuantModule, BaseQuantBlock)):
            t.act_quantizer.set_inited(False)
            # Enable timewise_quant_mode for modules if calibration involves time steps
            # This part is typically controlled by an argument or heuristic
            # For this context, it's assumed to be enabled where needed.
            if isinstance(cali_data, tuple) and len(cali_data) > 1: # If calibration data includes time steps
                 t.act_quantizer.timewise_quant_mode = True
            else:
                 t.act_quantizer.timewise_quant_mode = False

    # If cali_data is a tuple (data, t, class_labels), pass data and t for calibration
    if isinstance(cali_data, tuple):
        data_batch = cali_data[0]
        t_batch = cali_data[1]
        model_input_for_cali = [data_batch[0 : batch_size]]
        if len(cali_data) > 1:
            model_input_for_cali.append(t_batch[0 : batch_size])
        if len(cali_data) > 2: # assuming class labels
            model_input_for_cali.append(cali_data[2][0:batch_size])

        with torch.no_grad():
            for i in range(int(data_batch.size(0) / batch_size)):
                current_data_input = [item[i * batch_size : (i + 1) * batch_size].cuda() for item in cali_data]
                module(*current_data_input)
        torch.cuda.empty_cache()

        for t_mod in module.modules(): # Renamed t to t_mod to avoid conflict
            if isinstance(t_mod, (QuantModule, BaseQuantBlock)):
                t_mod.act_quantizer.set_inited(True)
    else:
        batch_size_effective = min(batch_size, cali_data.size(0))
        with torch.no_grad():
            for i in range(int(cali_data.size(0) / batch_size_effective)):
                module(cali_data[i * batch_size_effective : (i + 1) * batch_size_effective].cuda())
        torch.cuda.empty_cache()

        for t_mod in module.modules():
            if isinstance(t_mod, (QuantModule, BaseQuantBlock)):
                t_mod.act_quantizer.set_inited(True)


