def block_reconstruction(model: QuantModel, block: BaseQuantBlock, cali_data: torch.Tensor,
                         batch_size: int = 32, iters: int = 20000, weight: float = 0.01, opt_mode: str = 'mse',
                         act_quant: bool = False, b_range: tuple = (20, 2),
                         warmup: float = 0.0, p: float = 2.0, lr: float = 4e-5, wwq: bool = True, waq: bool = True,
                         order: str = 'together', input_prob: float = 1.0, keep_gpu: bool = True):

    cached_inps, cached_outs = get_init(model, block, cali_data, wq=wwq, aq=waq, batch_size=batch_size, input_prob=True, keep_gpu=keep_gpu)
    if act_quant and order == 'together':
        # Use actual calibration data's first component (images) for setting params
        set_act_quantize_params(block, cali_data=cali_data[0][:min(256, cali_data[0].size(0))], awq=True, order=order)

    cur_weight, cur_act = weight_get_quant_state(order, act_quant)
    block.set_quant_state(cur_weight, cur_act)

    round_mode = 'learned_hard_sigmoid'
    w_para, a_para = [], []
    w_opt, a_opt = None, None
    scheduler, a_scheduler = None, None

    for module in block.modules():
        if isinstance(module, QuantModule):
            module.weight_quantizer = AdaRoundQuantizer(uaq=module.weight_quantizer, round_mode=round_mode,
                                                        weight_tensor=module.org_weight.data)
            module.weight_quantizer.soft_targets = True
            w_para += [module.weight_quantizer.alpha]
        if isinstance(module, (QuantModule, BaseQuantBlock)): # Check BaseQuantBlock too
            if act_quant and order == 'together' and module.act_quantizer.delta is not None:
                # Only parameterize if delta is not None (i.e. already initialized)
                if not isinstance(module.act_quantizer.delta, nn.Parameter):
                    module.act_quantizer.delta = torch.nn.Parameter(torch.tensor(module.act_quantizer.delta))
                a_para += [module.act_quantizer.delta]
            module.act_quantizer.is_training = True

    if len(w_para) != 0:
        w_opt = torch.optim.Adam(w_para)
    if len(a_para) != 0:
        a_opt = torch.optim.Adam(a_para, lr=lr)
        a_scheduler = torch.optim.lr_scheduler.CosineAnnealingLR(a_opt, T_max=iters, eta_min=0.)

    loss_mode = 'relaxation'
    rec_loss = opt_mode
    loss_func = LossFunction(block, round_loss=loss_mode, weight=weight, max_count=iters, rec_loss=rec_loss,
                             b_range=b_range, decay_start=0, warmup=warmup, p=p)
    device = 'cuda'
    sz = cached_inps[0].size(0)
    for i in range(iters):
        idx = torch.randint(0, sz, (batch_size,))
        # cached_inps is a tuple of (input_data, input_symbolic_representation) if input_prob is True
        # cali_data could be (images, t, class_labels), so cached_inps needs to respect this.
        # If input_prob is True, cached_inps is (cached_data, cached_sym), where cached_data corresponds to the full input tuple (img, t, y)
        # This needs careful indexing assuming cali_data is (img, t, y_label)
        # Assuming cached_inps is a tuple, where first element is the input tuple (img, t, y) and second is its symbolic version
        cur_input_tuple = tuple(inp[idx].to(device) for inp in cached_inps[0]) 
        cur_sym_input_tuple = tuple(inp[idx].to(device) for inp in cached_inps[1])

        # Apply input_prob logic to each component of the input tuple if needed
        if input_prob < 1.0:
            # This part needs to be more complex if t and y should also be mixed, but typically input_prob is for image only
            # For simplicity, applying only to the first element (image)
            processed_input_tuple = list(cur_input_tuple)
            processed_input_tuple[0] = torch.where(torch.rand_like(processed_input_tuple[0]) < input_prob, processed_input_tuple[0], cur_sym_input_tuple[0])
            cur_input_tuple = tuple(processed_input_tuple)

        cur_out = cached_outs[idx].to(device)
        w_opt.zero_grad()
        if a_opt:
            a_opt.zero_grad()
        out_quant = block(*cur_input_tuple) # Pass as tuple

        err = loss_func(out_quant, cur_out)

        err.backward(retain_graph=True)

        w_opt.step()
        if a_opt:
            a_opt.step()
        if scheduler:
            scheduler.step()
        if a_scheduler:
            a_scheduler.step()
    torch.cuda.empty_cache()

    for module in block.modules():
        if isinstance(module, QuantModule):
            module.weight_quantizer.soft_targets = False
        if isinstance(module, (QuantModule, BaseQuantBlock)): # Check BaseQuantBlock too
            module.act_quantizer.is_training = False

    if act_quant and order == 'after' and waq:
        set_act_quantize_params(block, cali_data[0] if isinstance(cali_data, tuple) else cali_data, awq=True, order=order)

