def p_sample_loop_progressive_quant(self, model, shape, noise=None, clip_denoised=True, denoised_fn=None, model_kwargs=None, device=None, progress=False):
    if device is None:
        device = next(model.parameters()).device
    assert isinstance(shape, (tuple, list))
    if noise is not None:
        img = noise
    else:
        img = th.randn(*shape, device=device)
    indices = list(range(self.num_timesteps))[::-1]

    if progress:
        from tqdm.auto import tqdm
        indices = tqdm(indices)

    for now_rt, i in enumerate(indices):
        # Loop through all modules in the model to update activation quantizers
        for name, module in model.named_modules():
            if (
                isinstance(module, (QuantModule, BaseQuantBlock))
                and module.act_quantizer.timewise_quant_mode
            ):
                module.act_quantizer.change_timestep(
                    self.num_timesteps - now_rt - 1
                )
        t = th.tensor([i] * shape[0], device=device)
        with th.no_grad():
            out = self.p_sample(
                model,
                img,
                t,
                clip_denoised=clip_denoised,
                denoised_fn=denoised_fn,
                model_kwargs=model_kwargs,
            )
            out["input"] = img
            yield out
            img = out["sample"]

