def generate_t(args, t_mode, num_samples, diffusion, device):
    if t_mode == "normal":
        shape = torch.Tensor(num_samples)
        normal_val = torch.nn.init.normal_(shape, mean=args.calib_t_mode_normal_mean, std=args.calib_t_mode_normal_std)*diffusion.num_timesteps
        t = normal_val.clone().type(torch.int).to(device=device)
    # Other t_mode options like "random", "uniform", etc. are omitted for brevity as "normal" is most relevant for method description
    else:
        t = torch.randint(0, diffusion.num_timesteps, [num_samples], device=device) # Defaulting to random if not normal for simplicity

    return t.clamp(0, diffusion.num_timesteps - 1)

# Assuming load_data function is available from improved_diffusion.image_datasets
def backward_t_calib_data_generator(
    model, args, num_samples, device, t_mode, diffusion, class_cond=True
):
    model_kwargs = {}
    if class_cond:
        cls = torch.tensor([1] * num_samples, device=device).long() # Simplified class gen
        model_kwargs["y"] = cls
    loop_fn = (
        diffusion.ddim_sample_loop_progressive_quant # Using the modified quant loop
        if args.use_ddim
        else p_sample_loop_progressive_quant # Using the modified quant loop
    )
    t_indices = generate_t(args, t_mode, num_samples, diffusion, device).long()

    calib_data = None
    # Iterate through the progressive sampling process
    for now_rt_step, sample_step_output in enumerate(
        loop_fn(
            model,
            (num_samples, 3, args.image_size, args.image_size),
            clip_denoised=args.clip_denoised,
            model_kwargs=model_kwargs,
            device=device,
        )
    ):
        # Get the sample image at this step
        sample_t = sample_step_output["sample"]

        # Initialize calib_data tensor once if not already done
        if calib_data is None:
            calib_data = torch.zeros_like(sample_t)

        # Create a mask for samples that need to be collected at this specific timestep (now_rt_step)
        # Note: t_indices contains the target timesteps for each sample to be collected
        # The `now_rt_step` corresponds to the current diffusion step in reverse (T to 0)
        # The actual timestep 't' is (self.num_timesteps - 1 - now_rt_step)
        current_diffusion_timestep = diffusion.num_timesteps - 1 - now_rt_step
        mask = (t_indices == current_diffusion_timestep).float().view(-1, 1, 1, 1)

        # Add samples where the mask is active
        calib_data += sample_t * mask

    calib_data = calib_data.to(device)
    t_scaled = diffusion._scale_timesteps(t_indices)
    if class_cond:
        return calib_data, t_scaled, cls.to(device)
    else:
        return calib_data, t_scaled

def quant_model(args, model, diffusion):
